export type AppStep = 'ELIGIBILITY' | 'CREDIT_APP' | 'DOCUMENTS' | 'SUCCESS' | 'ADMIN_DASHBOARD';

export interface EligibilityData {
  language: 'English' | 'Español';
  name: string;
  phone: string;
  email: string;
  wantAppointment: boolean;
  appointmentDetails: string;
  landStatus: string;
  landLocation: string;
  utilities: string;
  bedrooms: string;
  targetPayment: number;
  employmentStatus: string;
  monthlyIncome: number;
  creditEstimate: string;
  downPayment: number;
  downPaymentSource: string;
  repoHistory: string;
  internalScore: number;
  date: string;
}

export interface CreditAppData {
  ssn: string;
  dob: string;
  currentAddress: string;
  yearsAtAddress: string;
  employerName: string;
  jobTitle: string;
  employerPhone: string;
  yearsEmployed: string;
  coApplicantName?: string;
  coApplicantSsn?: string;
}

export interface DocumentFile {
  id: string;
  name: string;
  type: string;
  data: string; // Base64
  category: 'bank_statement' | 'pay_stub' | 'license' | 'ss_card';
}

export interface LeadApplication {
  id: string;
  status: 'Pending' | 'Reviewing' | 'Approved' | 'Denied';
  eligibility: EligibilityData;
  creditApp?: CreditAppData;
  documents: DocumentFile[];
  submittedAt: string;
}

export interface AppState {
  currentStep: AppStep;
  eligibility?: EligibilityData;
  creditApp?: CreditAppData;
  documents: DocumentFile[];
  isAdmin: boolean;
}

import React from 'react';

export const ADMIN_PASSWORD = "heritage";

export const CONTACT_INFO = [
  { name: "Miza", phone: "701-441-1388" },
  { name: "Eva", phone: "405-268-2502" }
];

export const calculateScore = (data: {
  landStatus: string;
  utilities: string;
  employmentStatus: string;
  monthlyIncome: number;
  targetPayment: number;
  downPayment: number;
  creditEstimate: string;
  repoHistory: string;
}): number => {
  let score = 0;

  // Land Score
  if (data.landStatus.includes("Paid Off")) score += 30;
  else if (data.landStatus.includes("Financed")) score += 20;
  else if (data.landStatus.toLowerCase().includes("park")) score += 15;

  // Utilities Score
  if (data.utilities === "Yes, all utilities") score += 10;

  // Employment Score
  if (data.employmentStatus.includes("W2")) score += 15;
  else if (data.employmentStatus.includes("Fixed")) score += 10;

  // Income Score (Affordability)
  if (data.targetPayment > 0) {
    if (data.monthlyIncome > (data.targetPayment * 2.5)) score += 20;
  }

  // Asset Score
  if (data.downPayment > 2000) score += 10;

  // Credit Score
  if (data.creditEstimate.includes("Excellent") || data.creditEstimate.includes("Good")) score += 20;
  else if (data.creditEstimate.includes("Fair")) score += 5;

  // Negative History
  if (data.repoHistory === "Yes (Within last 2 years)") score -= 30;

  return score;
};

