import { LeadApplication } from '../types';

const STORAGE_KEY = 'heritage_applications';

export const storageService = {
  saveApplication: (app: LeadApplication): void => {
    const existing = storageService.getApplications();
    const updated = [app, ...existing];
    localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
  },

  getApplications: (): LeadApplication[] => {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  },

  updateApplicationStatus: (id: string, status: LeadApplication['status']): void => {
    const apps = storageService.getApplications();
    const index = apps.findIndex(a => a.id === id);
    if (index !== -1) {
      apps[index].status = status;
      localStorage.setItem(STORAGE_KEY, JSON.stringify(apps));
    }
  },

  deleteApplication: (id: string): void => {
    const apps = storageService.getApplications();
    const filtered = apps.filter(a => a.id !== id);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(filtered));
  }
};

import React, { useState, useEffect } from 'react';
import { AppStep, EligibilityData, CreditAppData, DocumentFile, LeadApplication } from './types';
import EligibilityForm from './components/EligibilityForm';
import CreditAppForm from './components/CreditAppForm';
import DocumentUpload from './components/DocumentUpload';
import Dashboard from './components/Dashboard';
import SuccessScreen from './components/SuccessScreen';
import { storageService } from './services/storageService';

const App: React.FC = () => {
  const [currentStep, setCurrentStep] = useState<AppStep>('ELIGIBILITY');
  const [eligibility, setEligibility] = useState<EligibilityData | undefined>();
  const [creditApp, setCreditApp] = useState<CreditAppData | undefined>();
  const [documents, setDocuments] = useState<DocumentFile[]>([]);
  const [isAdmin, setIsAdmin] = useState(false);

  // Check if we should start in Admin mode from hash
  useEffect(() => {
    if (window.location.hash === '#admin') {
      setCurrentStep('ADMIN_DASHBOARD');
    }
  }, []);

  const handleEligibilitySubmit = (data: EligibilityData) => {
    setEligibility(data);
    setCurrentStep('CREDIT_APP');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleCreditAppSubmit = (data: CreditAppData) => {
    setCreditApp(data);
    setCurrentStep('DOCUMENTS');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDocumentSubmit = (docs: DocumentFile[]) => {
    if (!eligibility) return;

    const newApp: LeadApplication = {
      id: `APP-${Date.now()}`,
      status: 'Pending',
      eligibility: eligibility,
      creditApp: creditApp,
      documents: docs,
      submittedAt: new Date().toISOString()
    };

    storageService.saveApplication(newApp);
    setCurrentStep('SUCCESS');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const renderStep = () => {
    switch (currentStep) {
      case 'ELIGIBILITY':
        return <EligibilityForm onSubmit={handleEligibilitySubmit} />;
      case 'CREDIT_APP':
        return (
          <CreditAppForm 
            onBack={() => setCurrentStep('ELIGIBILITY')} 
            onSubmit={handleCreditAppSubmit} 
          />
        );
      case 'DOCUMENTS':
        return (
          <DocumentUpload 
            onBack={() => setCurrentStep('CREDIT_APP')} 
            onSubmit={handleDocumentSubmit} 
          />
        );
      case 'SUCCESS':
        return <SuccessScreen eligibility={eligibility} onRestart={() => window.location.reload()} />;
      case 'ADMIN_DASHBOARD':
        return <Dashboard onLogout={() => { window.location.hash = ''; setCurrentStep('ELIGIBILITY'); }} />;
      default:
        return <EligibilityForm onSubmit={handleEligibilitySubmit} />;
    }
  };

  return (
    <div className="min-h-screen pb-12">
      {/* Navigation / Header */}
      <header className="bg-slate-900 text-white shadow-lg sticky top-0 z-50">
        <div className="max-w-4xl mx-auto px-4 py-4 flex justify-between items-center">
          <div className="flex items-center gap-3 cursor-pointer" onClick={() => !isAdmin && window.location.reload()}>
            <div className="bg-white p-1.5 rounded-lg">
              <img src="https://cdn-icons-png.flaticon.com/512/25/25694.png" className="w-8 h-8" alt="Logo" />
            </div>
            <div>
              <h1 className="text-xl font-bold tracking-tight">Heritage Housing</h1>
              <p className="text-xs text-slate-400 font-medium uppercase tracking-widest">Application Portal</p>
            </div>
          </div>

          <div className="hidden md:flex items-center gap-4">
             {currentStep !== 'ADMIN_DASHBOARD' && (
                <button 
                  onClick={() => { window.location.hash = 'admin'; setCurrentStep('ADMIN_DASHBOARD'); }}
                  className="text-xs font-semibold text-slate-400 hover:text-white transition-colors"
                >
                  ADMIN LOGIN
                </button>
             )}
          </div>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="max-w-4xl mx-auto px-4 pt-8">
        {renderStep()}
      </main>

      {/* Footer Support */}
      <footer className="mt-20 border-t border-slate-200 py-10 px-4 bg-white">
        <div className="max-w-4xl mx-auto">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div>
              <h3 className="font-bold text-slate-900 mb-4">Questions? We're here to help.</h3>
              <div className="space-y-3">
                <div className="flex items-center gap-3 text-slate-600">
                  <div className="w-8 h-8 bg-blue-50 rounded-full flex items-center justify-center text-blue-600">
                    <i className="fa-solid fa-phone text-sm"></i>
                  </div>
                  <div>
                    <p className="text-xs font-semibold text-slate-400">Miza</p>
                    <p className="font-medium">701-441-1388</p>
                  </div>
                </div>
                <div className="flex items-center gap-3 text-slate-600">
                  <div className="w-8 h-8 bg-blue-50 rounded-full flex items-center justify-center text-blue-600">
                    <i className="fa-solid fa-phone text-sm"></i>
                  </div>
                  <div>
                    <p className="text-xs font-semibold text-slate-400">Eva</p>
                    <p className="font-medium">405-268-2502</p>
                  </div>
                </div>
              </div>
            </div>
            <div className="bg-slate-50 p-6 rounded-2xl border border-slate-100">
              <p className="text-sm text-slate-600 mb-2">Heritage Housing Mobile Home Experts</p>
              <p className="text-xs text-slate-400 leading-relaxed">
                By submitting this application, you agree to our Terms of Service and Privacy Policy. 
                We use secure encryption for all document uploads. No SSN is stored until the formal Credit Application step.
              </p>
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { DocumentFile } from '../types';
import { Icons } from '../constants';

interface Props {
  onSubmit: (docs: DocumentFile[]) => void;
  onBack: () => void;
}

const DocumentUpload: React.FC<Props> = ({ onSubmit, onBack }) => {
  const [uploadedDocs, setUploadedDocs] = useState<DocumentFile[]>([]);
  const [isUploading, setIsUploading] = useState(false);

  const categories: { key: DocumentFile['category']; label: string; sub: string }[] = [
    { key: 'bank_statement', label: 'Last 3 Bank Statements', sub: 'PDF or Photos' },
    { key: 'pay_stub', label: 'Last Pay Check / Proof of Income', sub: 'Most recent pay stub' },
    { key: 'license', label: 'Driver\'s License / ID', sub: 'Front photo clearly showing name' },
    { key: 'ss_card', label: 'Social Security Card', sub: 'Clear photo of physical card' }
  ];

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>, category: DocumentFile['category']) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    setIsUploading(true);
    const newDocs: DocumentFile[] = [];

    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      const reader = new FileReader();

      const filePromise = new Promise<DocumentFile>((resolve) => {
        reader.onload = () => {
          resolve({
            id: `${Date.now()}-${Math.random()}`,
            name: file.name,
            type: file.type,
            data: reader.result as string,
            category: category
          });
        };
        reader.readAsDataURL(file);
      });

      const doc = await filePromise;
      newDocs.push(doc);
    }

    setUploadedDocs(prev => [...prev, ...newDocs]);
    setIsUploading(false);
  };

  const removeDoc = (id: string) => {
    setUploadedDocs(prev => prev.filter(d => d.id !== id));
  };

  const isComplete = () => {
    const keys = new Set(uploadedDocs.map(d => d.category));
    return categories.every(cat => keys.has(cat.key));
  };

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden animate-fade-in">
      <div className="p-8 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-slate-900 flex items-center gap-2">
            <Icons.Upload /> Document Upload
          </h2>
          <p className="text-slate-500 mt-1">Please provide the necessary documentation to verify your application.</p>
        </div>
        <button onClick={onBack} className="text-slate-400 hover:text-slate-600 p-2">
          <i className="fa-solid fa-xmark text-xl"></i>
        </button>
      </div>

      <div className="p-8 space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {categories.map((cat) => (
            <div key={cat.key} className="p-6 rounded-2xl border-2 border-dashed border-slate-200 bg-slate-50 hover:border-blue-300 transition-colors group relative">
              <div className="flex items-start justify-between mb-4">
                <div>
                  <h4 className="font-bold text-slate-900">{cat.label}</h4>
                  <p className="text-xs text-slate-500">{cat.sub}</p>
                </div>
                {uploadedDocs.some(d => d.category === cat.key) ? (
                  <span className="bg-green-100 text-green-600 px-2 py-1 rounded text-[10px] font-bold uppercase tracking-wider">
                    Uploaded
                  </span>
                ) : (
                  <span className="bg-slate-200 text-slate-500 px-2 py-1 rounded text-[10px] font-bold uppercase tracking-wider">
                    Pending
                  </span>
                )}
              </div>

              <div className="space-y-2 mb-4">
                {uploadedDocs.filter(d => d.category === cat.key).map(doc => (
                  <div key={doc.id} className="flex items-center justify-between text-xs bg-white p-2 rounded-lg border border-slate-100">
                    <span className="truncate max-w-[150px]">{doc.name}</span>
                    <button onClick={() => removeDoc(doc.id)} className="text-red-500 hover:text-red-700">
                      <i className="fa-solid fa-trash"></i>
                    </button>
                  </div>
                ))}
              </div>

              <label className="block w-full">
                <span className="sr-only">Choose file</span>
                <input 
                  type="file" multiple
                  className="block w-full text-sm text-slate-500
                    file:mr-4 file:py-2 file:px-4
                    file:rounded-full file:border-0
                    file:text-sm file:font-semibold
                    file:bg-blue-50 file:text-blue-700
                    hover:file:bg-blue-100 cursor-pointer
                  "
                  onChange={(e) => handleFileUpload(e, cat.key)}
                />
              </label>
            </div>
          ))}
        </div>

        <div className="bg-blue-50 p-4 rounded-xl flex items-center gap-3 text-blue-700">
          <i className="fa-solid fa-circle-info"></i>
          <p className="text-sm">We recommend uploading high-quality photos or PDFs to speed up processing.</p>
        </div>

        <div className="flex gap-4 pt-4">
          <button
            onClick={onBack}
            className="flex-1 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold py-4 px-6 rounded-2xl transition-all"
          >
            Back
          </button>
          <button
            onClick={() => onSubmit(uploadedDocs)}
            disabled={!isComplete() || isUploading}
            className={`flex-[2] font-bold py-4 px-6 rounded-2xl shadow-xl transition-all transform hover:-translate-y-1 flex items-center justify-center gap-2 ${isComplete() ? 'bg-green-600 hover:bg-green-700 text-white shadow-green-200' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}
          >
            {isUploading ? 'Uploading...' : 'Submit Complete Application'} <i className="fa-solid fa-check"></i>
          </button>
        </div>
      </div>
    </div>
  );
};

export default DocumentUpload;

import React, { useState, useEffect } from 'react';
import { LeadApplication } from '../types';
import { storageService } from '../services/storageService';
import { Icons, ADMIN_PASSWORD } from '../constants';

interface Props {
  onLogout: () => void;
}

const Dashboard: React.FC<Props> = ({ onLogout }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [password, setPassword] = useState('');
  const [apps, setApps] = useState<LeadApplication[]>([]);
  const [search, setSearch] = useState('');
  const [selectedApp, setSelectedApp] = useState<LeadApplication | null>(null);

  useEffect(() => {
    if (isAuthenticated) {
      setApps(storageService.getApplications());
    }
  }, [isAuthenticated]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (password === ADMIN_PASSWORD) {
      setIsAuthenticated(true);
    } else {
      alert("Invalid password");
    }
  };

  const updateStatus = (id: string, status: LeadApplication['status']) => {
    storageService.updateApplicationStatus(id, status);
    setApps(storageService.getApplications());
    if (selectedApp?.id === id) setSelectedApp({...selectedApp, status});
  };

  const deleteApp = (id: string) => {
    if (confirm("Are you sure you want to delete this application?")) {
      storageService.deleteApplication(id);
      setApps(storageService.getApplications());
      setSelectedApp(null);
    }
  };

  const downloadFile = (doc: { data: string, name: string }) => {
    const link = document.createElement('a');
    link.href = doc.data;
    link.download = doc.name;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  if (!isAuthenticated) {
    return (
      <div className="max-w-md mx-auto mt-20 p-8 bg-white rounded-3xl shadow-xl border border-slate-200 text-center animate-fade-in">
        <div className="bg-slate-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-6">
          <i className="fa-solid fa-lock text-slate-400 text-2xl"></i>
        </div>
        <h2 className="text-2xl font-bold text-slate-900 mb-2">Admin Access</h2>
        <p className="text-slate-500 mb-8">Please enter the administrator password to continue.</p>
        <form onSubmit={handleLogin} className="space-y-4">
          <input 
            type="password" autoFocus
            className="w-full px-4 py-3 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-center text-lg tracking-widest"
            placeholder="••••••••"
            value={password}
            onChange={e => setPassword(e.target.value)}
          />
          <button className="w-full bg-slate-900 hover:bg-black text-white font-bold py-3 rounded-xl transition-all">
            Unlock Dashboard
          </button>
        </form>
      </div>
    );
  }

  const filteredApps = apps.filter(a => 
    a.eligibility.name.toLowerCase().includes(search.toLowerCase()) || 
    a.eligibility.phone.includes(search)
  );

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex justify-between items-center mb-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-900">Application Dashboard</h2>
          <p className="text-slate-500">Managing {apps.length} total applications</p>
        </div>
        <div className="flex gap-3">
            <button onClick={() => setApps(storageService.getApplications())} className="p-2 bg-white border rounded-xl hover:bg-slate-50">
              <i className="fa-solid fa-rotate"></i>
            </button>
            <button onClick={onLogout} className="bg-red-50 text-red-600 px-4 py-2 rounded-xl font-bold text-sm hover:bg-red-100 transition-all">
              Log Out
            </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* List Panel */}
        <div className="lg:col-span-1 space-y-4">
          <div className="relative">
            <i className="fa-solid fa-search absolute left-4 top-1/2 -translate-y-1/2 text-slate-400"></i>
            <input 
              type="text" placeholder="Search by name or phone..."
              className="w-full pl-10 pr-4 py-3 border rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none bg-white shadow-sm"
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
          </div>

          <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm h-[600px] overflow-y-auto">
            {filteredApps.map(app => (
              <button 
                key={app.id}
                onClick={() => setSelectedApp(app)}
                className={`w-full p-4 border-b border-slate-100 flex items-start gap-4 transition-all text-left ${selectedApp?.id === app.id ? 'bg-blue-50 border-l-4 border-l-blue-600' : 'hover:bg-slate-50'}`}
              >
                <div className={`w-10 h-10 rounded-full flex items-center justify-center text-white shrink-0 ${app.eligibility.internalScore >= 60 ? 'bg-green-500' : app.eligibility.internalScore >= 40 ? 'bg-amber-500' : 'bg-red-500'}`}>
                  {app.eligibility.name.charAt(0)}
                </div>
                <div className="min-w-0">
                  <h4 className="font-bold text-slate-900 truncate">{app.eligibility.name}</h4>
                  <p className="text-xs text-slate-500 mb-1">{app.eligibility.phone}</p>
                  <div className="flex items-center gap-2">
                    <span className={`text-[10px] px-1.5 py-0.5 rounded font-bold uppercase tracking-wider ${app.status === 'Approved' ? 'bg-green-100 text-green-700' : app.status === 'Denied' ? 'bg-red-100 text-red-700' : 'bg-blue-100 text-blue-700'}`}>
                      {app.status}
                    </span>
                    <span className="text-[10px] text-slate-400">
                      {new Date(app.submittedAt).toLocaleDateString()}
                    </span>
                  </div>
                </div>
              </button>
            ))}
            {filteredApps.length === 0 && (
              <div className="p-8 text-center text-slate-400 italic">No applications found.</div>
            )}
          </div>
        </div>

        {/* Detail Panel */}
        <div className="lg:col-span-2">
          {selectedApp ? (
            <div className="bg-white rounded-2xl border border-slate-200 shadow-sm animate-fade-in overflow-hidden">
               <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                  <div>
                    <h3 className="text-xl font-bold text-slate-900">{selectedApp.eligibility.name}</h3>
                    <p className="text-sm text-slate-500">Submitted: {new Date(selectedApp.submittedAt).toLocaleString()}</p>
                  </div>
                  <div className="flex gap-2">
                    <select 
                      className="px-3 py-1 border rounded-lg text-sm font-medium"
                      value={selectedApp.status}
                      onChange={e => updateStatus(selectedApp.id, e.target.value as any)}
                    >
                      <option>Pending</option>
                      <option>Reviewing</option>
                      <option>Approved</option>
                      <option>Denied</option>
                    </select>
                    <button onClick={() => deleteApp(selectedApp.id)} className="p-1.5 text-red-400 hover:text-red-600">
                      <i className="fa-solid fa-trash"></i>
                    </button>
                  </div>
               </div>

               <div className="p-6 h-[700px] overflow-y-auto space-y-8">
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                    <div className="p-3 bg-slate-50 rounded-xl border border-slate-100">
                      <p className="text-[10px] font-bold text-slate-400 uppercase">Score</p>
