    }
  }, []);

  const handleEligibilitySubmit = (data: EligibilityData) => {
    setEligibility(data);
    setCurrentStep('CREDIT_APP');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleCreditAppSubmit = (data: CreditAppData) => {
    setCreditApp(data);
    setCurrentStep('DOCUMENTS');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDocumentSubmit = (docs: DocumentFile[]) => {
    if (!eligibility) return;

    const newApp: LeadApplication = {
      id: `APP-${Date.now()}`,
      status: 'Pending',
      eligibility: eligibility,
      creditApp: creditApp,
      documents: docs,
      submittedAt: new Date().toISOString()
