    storageService.saveApplication(newApp);
    setCurrentStep('SUCCESS');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const renderStep = () => {
    switch (currentStep) {
      case 'ELIGIBILITY':
