          <CreditAppForm 
            onBack={() => setCurrentStep('ELIGIBILITY')} 
            onSubmit={handleCreditAppSubmit} 
            eligibility={eligibility}
          />
        );
      case 'DOCUMENTS':
        return (
          <DocumentUpload 
            onBack={() => setCurrentStep('CREDIT_APP')} 
            onSubmit={handleDocumentSubmit} 
          />
        );
      case 'SUCCESS':
        return <SuccessScreen eligibility={eligibility} onRestart={() => window.location.reload()} />;
      case 'ADMIN_DASHBOARD':
        return <Dashboard onLogout={() => { window.location.hash = ''; setCurrentStep('ELIGIBILITY'); }} />;
      default:
        return <EligibilityForm onSubmit={handleEligibilitySubmit} initialData={eligibility} />;
