import React, { useState, useEffect } from 'react';
import { AppStep, EligibilityData, CreditAppData, DocumentFile, LeadApplication } from './types';
import LandingPage from './components/LandingPage';
import EligibilityForm from './components/EligibilityForm';
import CreditAppForm from './components/CreditAppForm';
import DocumentUpload from './components/DocumentUpload';
import Dashboard from './components/Dashboard';
import SuccessScreen from './components/SuccessScreen';
import { storageService } from './services/storageService';

const App: React.FC = () => {
  const [currentStep, setCurrentStep] = useState<AppStep>('LANDING');
  const [eligibility, setEligibility] = useState<EligibilityData | undefined>();
  const [creditApp, setCreditApp] = useState<CreditAppData | undefined>();
  const [documents, setDocuments] = useState<DocumentFile[]>([]);
  const [isAdmin, setIsAdmin] = useState(false);

  // Check if we should start in Admin mode from hash
  useEffect(() => {
    if (window.location.hash === '#admin') {
      setCurrentStep('ADMIN_DASHBOARD');
    }
  }, []);

  const handleEligibilitySubmit = (data: EligibilityData) => {
    setEligibility(data);
    setCurrentStep('CREDIT_APP');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleCreditAppSubmit = (data: CreditAppData) => {
    setCreditApp(data);
    setCurrentStep('DOCUMENTS');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDocumentSubmit = (docs: DocumentFile[]) => {
    if (!eligibility) return;

    const newApp: LeadApplication = {
      id: `APP-${Date.now()}`,
      status: 'Pending',
      eligibility: eligibility,
      creditApp: creditApp,
      documents: docs,
      submittedAt: new Date().toISOString()
    };

    storageService.saveApplication(newApp);
    setCurrentStep('SUCCESS');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const renderStep = () => {
    switch (currentStep) {
      case 'LANDING':
        return <LandingPage onStart={() => setCurrentStep('ELIGIBILITY')} />;
      case 'ELIGIBILITY':
        return (
          <EligibilityForm 
            onBack={() => setCurrentStep('LANDING')}
            onSubmit={handleEligibilitySubmit} 
            initialData={eligibility} 
          />
        );
      case 'CREDIT_APP':
        return (
          <CreditAppForm 
            onBack={() => setCurrentStep('ELIGIBILITY')} 
            onSubmit={handleCreditAppSubmit} 
            eligibility={eligibility}
          />
        );
      case 'DOCUMENTS':
        return (
          <DocumentUpload 
            onBack={() => setCurrentStep('CREDIT_APP')} 
            onSubmit={handleDocumentSubmit} 
          />
        );
      case 'SUCCESS':
        return <SuccessScreen eligibility={eligibility} onRestart={() => window.location.reload()} />;
      case 'ADMIN_DASHBOARD':
        return <Dashboard onLogout={() => { window.location.hash = ''; setCurrentStep('LANDING'); }} />;
      default:
        return <LandingPage onStart={() => setCurrentStep('ELIGIBILITY')} />;
    }
  };

  return (
    <div className="min-h-screen pb-12">
      <header className="bg-slate-900 text-white shadow-lg sticky top-0 z-50">
        <div className="max-w-4xl mx-auto px-4 py-4 flex justify-between items-center">
          <div className="flex items-center gap-3 cursor-pointer" onClick={() => { if(currentStep !== 'ADMIN_DASHBOARD') window.location.reload(); }}>
            <div className="bg-white p-1.5 rounded-lg">
              <img src="https://cdn-icons-png.flaticon.com/512/25/25694.png" className="w-8 h-8" alt="Logo" />
            </div>
            <div>
              <h1 className="text-xl font-bold tracking-tight">Heritage Housing</h1>
              <p className="text-xs text-slate-400 font-medium uppercase tracking-widest">Application Portal</p>
            </div>
          </div>

          <div className="hidden md:flex items-center gap-4">
             {currentStep !== 'ADMIN_DASHBOARD' && (
                <button 
                  onClick={() => { window.location.hash = 'admin'; setCurrentStep('ADMIN_DASHBOARD'); }}
                  className="text-xs font-semibold text-slate-400 hover:text-white transition-colors"
                >
                  ADMIN LOGIN
                </button>
             )}
          </div>
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-4 pt-8">
        {renderStep()}
      </main>

      <footer className="mt-20 border-t border-slate-200 py-10 px-4 bg-white">
        <div className="max-w-4xl mx-auto">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div>
              <h3 className="font-bold text-slate-900 mb-4">Questions? We're here to help.</h3>
              <div className="space-y-3">
                <div className="flex items-center gap-3 text-slate-600">
                  <div className="w-8 h-8 bg-blue-50 rounded-full flex items-center justify-center text-blue-600">
                    <i className="fa-solid fa-phone text-sm"></i>
                  </div>
                  <div>
                    <p className="text-xs font-semibold text-slate-400">Miza</p>
                    <p className="font-medium">701-441-1388</p>
                  </div>
                </div>
                <div className="flex items-center gap-3 text-slate-600">
                  <div className="w-8 h-8 bg-blue-50 rounded-full flex items-center justify-center text-blue-600">
                    <i className="fa-solid fa-phone text-sm"></i>
                  </div>
                  <div>
                    <p className="text-xs font-semibold text-slate-400">Eva</p>
                    <p className="font-medium">405-268-2502</p>
                  </div>
                </div>
              </div>
            </div>
            <div className="bg-slate-50 p-6 rounded-2xl border border-slate-100">
              <p className="text-sm text-slate-600 mb-2">Heritage Housing Mobile Home Experts</p>
              <p className="text-xs text-slate-400 leading-relaxed">
                By submitting this application, you agree to our Terms of Service and Privacy Policy. 
                We use secure encryption for all document uploads. No SSN is stored until the formal Credit Application step.
              </p>
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
};

