import React, { useState, useEffect } from 'react';
import { LeadApplication } from '../types';
import { storageService } from '../services/storageService';
import { Icons, ADMIN_PASSWORD } from '../constants';

interface Props {
  onLogout: () => void;
}

const Dashboard: React.FC<Props> = ({ onLogout }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [password, setPassword] = useState('');
  const [apps, setApps] = useState<LeadApplication[]>([]);
  const [search, setSearch] = useState('');
  const [selectedApp, setSelectedApp] = useState<LeadApplication | null>(null);

  useEffect(() => {
    if (isAuthenticated) {
      setApps(storageService.getApplications());
    }
  }, [isAuthenticated]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (password === ADMIN_PASSWORD) {
      setIsAuthenticated(true);
    } else {
      alert("Invalid password");
    }
  };

  const updateStatus = (id: string, status: LeadApplication['status']) => {
    storageService.updateApplicationStatus(id, status);
    setApps(storageService.getApplications());
    if (selectedApp?.id === id) setSelectedApp({...selectedApp, status});
  };

  const deleteApp = (id: string) => {
    if (confirm("Are you sure you want to delete this application?")) {
      storageService.deleteApplication(id);
      setApps(storageService.getApplications());
      setSelectedApp(null);
    }
  };

  const downloadFile = (doc: { data: string, name: string }) => {
    const link = document.createElement('a');
    link.href = doc.data;
    link.download = doc.name;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const getScoreColor = (score: number) => {
    if (score >= 60) return 'text-green-600 bg-green-50';
    if (score >= 40) return 'text-amber-600 bg-amber-50';
    return 'text-red-600 bg-red-50';
  };

  if (!isAuthenticated) {
    return (
      <div className="max-w-md mx-auto mt-20 p-8 bg-white rounded-3xl shadow-xl border border-slate-200 text-center animate-fade-in">
        <div className="bg-slate-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-6">
          <i className="fa-solid fa-lock text-slate-400 text-2xl"></i>
        </div>
        <h2 className="text-2xl font-bold text-slate-900 mb-2">Salesman Portal</h2>
        <p className="text-slate-500 mb-8">Access restricted to authorized Heritage Housing staff.</p>
        <form onSubmit={handleLogin} className="space-y-4">
          <input 
            type="password" autoFocus
            className="w-full px-4 py-3 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-center text-lg tracking-widest"
            placeholder="••••••••"
            value={password}
            onChange={e => setPassword(e.target.value)}
          />
          <button className="w-full bg-slate-900 hover:bg-black text-white font-bold py-3 rounded-xl transition-all">
            Unlock Sales Dashboard
          </button>
        </form>
      </div>
    );
  }

  const filteredApps = apps.filter(a => 
    a.eligibility.name.toLowerCase().includes(search.toLowerCase()) || 
    a.eligibility.phone.includes(search)
  );

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex justify-between items-center mb-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-900">Sales Dashboard</h2>
          <p className="text-slate-500">Managing {apps.length} leads</p>
        </div>
        <div className="flex gap-3">
            <button onClick={() => setApps(storageService.getApplications())} className="p-2 bg-white border rounded-xl hover:bg-slate-50">
              <i className="fa-solid fa-rotate"></i>
            </button>
            <button onClick={onLogout} className="bg-red-50 text-red-600 px-4 py-2 rounded-xl font-bold text-sm hover:bg-red-100 transition-all">
              Log Out
            </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* List Panel */}
        <div className="lg:col-span-1 space-y-4">
          <div className="relative">
            <i className="fa-solid fa-search absolute left-4 top-1/2 -translate-y-1/2 text-slate-400"></i>
            <input 
              type="text" placeholder="Search by name or phone..."
              className="w-full pl-10 pr-4 py-3 border rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none bg-white shadow-sm"
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
          </div>

          <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm h-[600px] overflow-y-auto">
            {filteredApps.map(app => (
              <button 
                key={app.id}
                onClick={() => setSelectedApp(app)}
                className={`w-full p-4 border-b border-slate-100 flex items-start gap-4 transition-all text-left ${selectedApp?.id === app.id ? 'bg-blue-50 border-l-4 border-l-blue-600' : 'hover:bg-slate-50'}`}
              >
                <div className={`w-10 h-10 rounded-full flex items-center justify-center text-white shrink-0 ${app.eligibility.internalScore >= 60 ? 'bg-green-500' : app.eligibility.internalScore >= 40 ? 'bg-amber-500' : 'bg-red-500'}`}>
                  {app.eligibility.name.charAt(0)}
                </div>
                <div className="min-w-0">
                  <h4 className="font-bold text-slate-900 truncate">{app.eligibility.name}</h4>
                  <p className="text-xs text-slate-500 mb-1">{app.eligibility.phone}</p>
                  <div className="flex items-center gap-2">
                    <span className={`text-[10px] px-1.5 py-0.5 rounded font-bold uppercase tracking-wider ${app.status === 'Approved' ? 'bg-green-100 text-green-700' : app.status === 'Denied' ? 'bg-red-100 text-red-700' : 'bg-blue-100 text-blue-700'}`}>
                      {app.status}
