                    <span className="text-[10px] text-slate-400 font-bold ml-auto">
                      {app.eligibility.internalScore} pts
                    </span>
                  </div>
                </div>
              </button>
            ))}
            {filteredApps.length === 0 && (
              <div className="p-8 text-center text-slate-400 italic">No applications found.</div>
            )}
          </div>
        </div>

        {/* Detail Panel */}
        <div className="lg:col-span-2">
          {selectedApp ? (
            <div className="bg-white rounded-2xl border border-slate-200 shadow-sm animate-fade-in overflow-hidden">
               <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
