            </div>
            <div>
              <h1 className="text-xl font-bold tracking-tight">Heritage Housing</h1>
              <p className="text-xs text-slate-400 font-medium uppercase tracking-widest">Application Portal</p>
            </div>
          </div>

          <div className="hidden md:flex items-center gap-4">
             {currentStep !== 'ADMIN_DASHBOARD' && (
                <button 
                  onClick={() => { window.location.hash = 'admin'; setCurrentStep('ADMIN_DASHBOARD'); }}
