import React, { useState } from 'react';
import { DocumentFile } from '../types';
import { Icons } from '../constants';

interface Props {
  onSubmit: (docs: DocumentFile[]) => void;
  onBack: () => void;
  hasCosigner: boolean;
}

const DocumentUpload: React.FC<Props> = ({ onSubmit, onBack, hasCosigner }) => {
  const [uploadedDocs, setUploadedDocs] = useState<DocumentFile[]>([]);
  const [isUploading, setIsUploading] = useState(false);

  const categories: { key: DocumentFile['category']; label: string; sub: string }[] = [
    { key: 'bank_statement', label: 'Last 3 Bank Statements', sub: 'PDF or Photos' },
    { key: 'pay_stub', label: 'Last Pay Check / Proof of Income', sub: 'Most recent pay stub' },
    { key: 'license', label: 'Driver\'s License / ID', sub: 'Front photo clearly showing name' },
    { key: 'ss_card', label: 'Social Security Card', sub: 'Clear photo of physical card' }
  ];

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>, category: DocumentFile['category'], owner: DocumentFile['owner']) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    setIsUploading(true);
    const newDocs: DocumentFile[] = [];

    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      const reader = new FileReader();

      const filePromise = new Promise<DocumentFile>((resolve) => {
        reader.onload = () => {
          resolve({
            id: `${Date.now()}-${Math.random()}`,
            name: file.name,
            type: file.type,
            data: reader.result as string,
            category: category,
            owner: owner
          });
        };
        reader.readAsDataURL(file);
      });

      const doc = await filePromise;
      newDocs.push(doc);
    }

    setUploadedDocs(prev => [...prev, ...newDocs]);
    setIsUploading(false);
  };

  const removeDoc = (id: string) => {
    setUploadedDocs(prev => prev.filter(d => d.id !== id));
  };

  const isComplete = () => {
    const applicantKeys = new Set(uploadedDocs.filter(d => d.owner === 'applicant').map(d => d.category));
    const mainComplete = categories.every(cat => applicantKeys.has(cat.key));

    if (hasCosigner) {
      const cosignerKeys = new Set(uploadedDocs.filter(d => d.owner === 'cosigner').map(d => d.category));
      return mainComplete && categories.every(cat => cosignerKeys.has(cat.key));
    }

    return mainComplete;
  };

  const DocumentSection = ({ owner, title }: { owner: DocumentFile['owner'], title: string }) => (
    <div className="space-y-6">
      <h3 className="text-xl font-black text-slate-800 border-l-4 border-blue-600 pl-4">{title}</h3>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {categories.map((cat) => (
          <div key={`${owner}-${cat.key}`} className="p-6 rounded-2xl border-2 border-dashed border-slate-200 bg-slate-50 hover:border-blue-300 transition-colors group relative">
            <div className="flex items-start justify-between mb-4">
              <div>
                <h4 className="font-bold text-slate-900">{cat.label}</h4>
                <p className="text-xs text-slate-500">{cat.sub}</p>
              </div>
              {uploadedDocs.some(d => d.category === cat.key && d.owner === owner) ? (
                <span className="bg-green-100 text-green-600 px-2 py-1 rounded text-[10px] font-bold uppercase tracking-wider">
                  Uploaded
                </span>
              ) : (
                <span className="bg-slate-200 text-slate-500 px-2 py-1 rounded text-[10px] font-bold uppercase tracking-wider">
                  Pending
                </span>
              )}
            </div>

            <div className="space-y-2 mb-4">
              {uploadedDocs.filter(d => d.category === cat.key && d.owner === owner).map(doc => (
                <div key={doc.id} className="flex items-center justify-between text-xs bg-white p-2 rounded-lg border border-slate-100 shadow-sm">
                  <span className="truncate max-w-[150px]">{doc.name}</span>
                  <button onClick={() => removeDoc(doc.id)} className="text-red-500 hover:text-red-700">
                    <i className="fa-solid fa-trash"></i>
                  </button>
                </div>
              ))}
            </div>

            <label className="block w-full">
              <input type="file" multiple className="block w-full text-xs text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-xs file:font-semibold file:bg-blue-50 file:text-blue-700 hover:file:bg-blue-100 cursor-pointer"
                onChange={(e) => handleFileUpload(e, cat.key, owner)} />
            </label>
          </div>
        ))}
      </div>
    </div>
  );

  return (
    <div className="bg-white rounded-[2rem] shadow-2xl border border-slate-100 overflow-hidden animate-fade-in">
      <div className="p-8 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-black text-slate-900 flex items-center gap-2">
            <Icons.Upload /> Document Upload
          </h2>
          <p className="text-slate-500 mt-1">Provide verification to complete your application.</p>
        </div>
        <button onClick={onBack} className="text-slate-400 hover:text-slate-600 p-2">
          <i className="fa-solid fa-arrow-left text-xl"></i>
        </button>
      </div>

      <div className="p-8 space-y-12">
        <DocumentSection owner="applicant" title="Main Applicant Documents" />

        {hasCosigner && (
          <DocumentSection owner="cosigner" title="Co-signer Documents" />
        )}

        <div className="bg-blue-50 p-6 rounded-2xl flex items-center gap-4 text-blue-700 border border-blue-100">
          <i className="fa-solid fa-circle-info text-2xl"></i>
          <p className="text-sm font-medium">Clear photos or PDFs of physical documents are best for fast processing.</p>
        </div>

        <div className="flex gap-4 pt-4">
          <button onClick={onBack} className="flex-1 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold py-4 px-6 rounded-2xl transition-all">
            Back
          </button>
          <button onClick={() => onSubmit(uploadedDocs)} disabled={!isComplete() || isUploading}
            className={`flex-[2] font-black py-4 px-6 rounded-2xl shadow-xl transition-all transform hover:-translate-y-1 flex items-center justify-center gap-2 ${isComplete() ? 'bg-green-600 hover:bg-green-700 text-white shadow-green-200' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}>
            {isUploading ? 'Uploading...' : 'Submit Final Application'} <i className="fa-solid fa-check"></i>
          </button>
        </div>
      </div>
    </div>
  );
};

export default DocumentUpload;

import React, { useState, useEffect } from 'react';
import { LeadApplication } from '../types';
import { storageService } from '../services/storageService';
import { Icons, ADMIN_PASSWORD } from '../constants';

interface Props {
  onLogout: () => void;
}

const Dashboard: React.FC<Props> = ({ onLogout }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [password, setPassword] = useState('');
  const [apps, setApps] = useState<LeadApplication[]>([]);
  const [search, setSearch] = useState('');
  const [selectedApp, setSelectedApp] = useState<LeadApplication | null>(null);

  useEffect(() => {
    if (isAuthenticated) {
      setApps(storageService.getApplications());
    }
  }, [isAuthenticated]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (password === ADMIN_PASSWORD) {
      setIsAuthenticated(true);
    } else {
      alert("Invalid password");
    }
  };

  const updateStatus = (id: string, status: LeadApplication['status']) => {
    storageService.updateApplicationStatus(id, status);
    setApps(storageService.getApplications());
    if (selectedApp?.id === id) setSelectedApp({...selectedApp, status});
  };

  const deleteApp = (id: string) => {
    if (confirm("Are you sure you want to delete this application?")) {
      storageService.deleteApplication(id);
      setApps(storageService.getApplications());
      setSelectedApp(null);
    }
  };

  const downloadFile = (doc: { data: string, name: string }) => {
    const link = document.createElement('a');
    link.href = doc.data;
    link.download = doc.name;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const getScoreColor = (score: number) => {
    if (score >= 60) return 'text-green-600 bg-green-50';
    if (score >= 40) return 'text-amber-600 bg-amber-50';
    return 'text-red-600 bg-red-50';
  };

  if (!isAuthenticated) {
    return (
      <div className="max-w-md mx-auto mt-20 p-8 bg-white rounded-3xl shadow-xl border border-slate-200 text-center animate-fade-in">
        <div className="bg-slate-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-6">
