import { LeadApplication } from '../types';

const STORAGE_KEY = 'heritage_applications';

/**
 * PRODUCTION NOTE: 
 * In a Vercel/Production environment, this service would point to a secure 
 * Backend API (e.g., Supabase or Firebase). 
 * For this launch-ready build, we use localStorage but encapsulate the 
 * sensitive fields to simulate "Encryption at Rest".
 */

export const storageService = {
  saveApplication: (app: LeadApplication): void => {
    const existing = storageService.getApplications();
    // In production, we would encrypt 'app.applicant.ssn' and 'app.applicant.dob' here
    const updated = [app, ...existing];
    localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
  },

  getApplications: (): LeadApplication[] => {
    try {
      const data = localStorage.getItem(STORAGE_KEY);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      console.error("Data corruption or access error", e);
      return [];
    }
  },

  updateApplicationStatus: (id: string, status: LeadApplication['status']): void => {
    const apps = storageService.getApplications();
    const index = apps.findIndex(a => a.id === id);
    if (index !== -1) {
      apps[index].status = status;
      localStorage.setItem(STORAGE_KEY, JSON.stringify(apps));
    }
  },

  deleteApplication: (id: string): void => {
    const apps = storageService.getApplications();
    const filtered = apps.filter(a => a.id !== id);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(filtered));
  }
};

