                    <span className={`text-[10px] px-1.5 py-0.5 rounded font-bold uppercase ${app.status === 'Approved' ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'}`}>{app.status}</span>
                    <span className="text-[10px] text-slate-400 ml-auto font-black">{app.applicant.internalScore} pts</span>
                  </div>
                </div>
              </button>
            ))}
          </div>
        </div>

        <div className="lg:col-span-2">
          {selectedApp ? (
            <div className="bg-white rounded-2xl border border-slate-200 shadow-sm animate-fade-in overflow-hidden">
