                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-4 text-sm">
                      <p><span className="text-slate-400 font-bold uppercase text-[10px] block">Phone</span> {selectedApp.applicant.phone}</p>
                      <p>
                        <span className="text-slate-400 font-bold uppercase text-[10px] block">SSN</span> 
                        <span className={!revealedFields[selectedApp.id] ? 'blur-[4px] select-none' : ''}>
