                      </p>
                      <p>
                        <span className="text-slate-400 font-bold uppercase text-[10px] block">DOB</span> 
                        <span className={!revealedFields[selectedApp.id] ? 'blur-[4px] select-none' : ''}>
                          {revealedFields[selectedApp.id] ? selectedApp.applicant.dob : 'MM/DD/YYYY'}
