                      </p>
                      <p><span className="text-slate-400 font-bold uppercase text-[10px] block">Address</span> {selectedApp.applicant.currentAddress}</p>
                      <p><span className="text-slate-400 font-bold uppercase text-[10px] block">Employer</span> {selectedApp.applicant.employerName}</p>
                      <p><span className="text-slate-400 font-bold uppercase text-[10px] block">Employment</span> {selectedApp.applicant.employmentStatus}</p>
                      <p><span className="text-slate-400 font-bold uppercase text-[10px] block">Bedrooms Needed</span> {selectedApp.applicant.bedrooms}</p>
                      <p><span className="text-slate-400 font-bold uppercase text-[10px] block">Property Status</span> {selectedApp.applicant.landStatus}</p>
                    </div>
                  </section>

                  {/* Co-signer Details */}
                  {selectedApp.cosigner && (
                    <section className="bg-blue-50 p-6 rounded-2xl border border-blue-100 space-y-4">
                      <h4 className="font-black text-blue-800 border-b border-blue-100 pb-2 uppercase tracking-wide text-xs">Co-signer Information ({selectedApp.cosigner.relationship})</h4>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-4 text-sm">
                        <p><span className="text-blue-400 font-bold uppercase text-[10px] block">Name</span> {selectedApp.cosigner.name}</p>
                        <p><span className="text-blue-400 font-bold uppercase text-[10px] block">Phone</span> {selectedApp.cosigner.phone}</p>
                        <p>
                          <span className="text-blue-400 font-bold uppercase text-[10px] block">SSN</span> 
                          <span className={!revealedFields[selectedApp.id] ? 'blur-[4px] select-none' : ''}>
                             {revealedFields[selectedApp.id] ? selectedApp.cosigner.ssn : maskSSN(selectedApp.cosigner.ssn)}
                          </span>
                        </p>
                        <p><span className="text-blue-400 font-bold uppercase text-[10px] block">Income</span> ${selectedApp.cosigner.monthlyIncome}</p>
                        <p><span className="text-blue-400 font-bold uppercase text-[10px] block">Employer</span> {selectedApp.cosigner.employerName}</p>
                      </div>
                    </section>
                  )}

                  {/* Documents */}
                  <section className="space-y-4">
                    <h4 className="font-black text-slate-800 border-b pb-2 uppercase tracking-wide text-xs">Secured Documents</h4>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                      {selectedApp.documents.map(doc => (
                        <div key={doc.id} className="flex items-center justify-between bg-white border border-slate-200 p-3 rounded-xl hover:border-blue-300 transition-colors group">
                          <div className="min-w-0">
                            <p className="text-xs font-bold text-slate-800 truncate">{doc.name}</p>
                            <p className="text-[9px] text-slate-400 uppercase font-black">{doc.owner} - {doc.category.replace('_', ' ')}</p>
                          </div>
                          <button onClick={() => downloadFile(doc)} className="text-blue-600 hover:text-blue-800 p-2 transform group-hover:scale-110 transition-transform"><Icons.Download /></button>
                        </div>
                      ))}
                    </div>
                  </section>
               </div>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-center p-12 bg-slate-50 rounded-2xl border-2 border-dashed border-slate-200 text-slate-400">
