                </div>
                <div className="flex-1">
                   <div className="border-b-2 border-black h-12"></div>
                   <p className="text-[9px] font-bold uppercase mt-1">Authorized Management Review</p>
                </div>
              </div>
              <p className="text-[7px] text-slate-500 mt-8 italic leading-tight text-center">
                This document is for internal verification by Heritage Housing Sales Personnel only. Any unauthorized duplication or distribution is strictly prohibited. Final approval is subject to manual verification of all submitted bank statements and pay stubs.
              </p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// HELPER COMPONENTS
const DataRow = ({ label, value, masked = false, colSpan = 1 }: { label: string, value: string, masked?: boolean, colSpan?: number }) => (
  <div className={`space-y-1 ${colSpan > 1 ? 'md:col-span-2' : ''}`}>
    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{label}</p>
    <p className={`text-sm font-bold text-slate-900 border-b border-slate-50 pb-1 ${masked ? 'blur-[4px] select-none opacity-50' : ''}`}>
      {value || 'Not Provided'}
    </p>
  </div>
);

const PrintField = ({ label, value, colSpan = 1 }: { label: string, value: string, colSpan?: number }) => (
  <div className={colSpan > 1 ? 'col-span-2' : ''}>
    <p className="text-[8px] font-bold text-slate-500 uppercase tracking-tighter leading-none mb-1">{label}</p>
    <p className="text-sm font-black text-black border-b border-slate-200 pb-1">{value || 'N/A'}</p>
  </div>
);

export default Dashboard;

import React, { useState, useEffect, useRef } from 'react';
import { LeadApplication } from '../types';
import { storageService } from '../services/storageService';
import { Icons, ADMIN_PASSWORD } from '../constants';

interface Props {
  onLogout: () => void;
}

type DashboardView = 'table' | 'profile';

const Dashboard: React.FC<Props> = ({ onLogout }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [password, setPassword] = useState('');
  const [apps, setApps] = useState<LeadApplication[]>([]);
  const [search, setSearch] = useState('');
  const [selectedApp, setSelectedApp] = useState<LeadApplication | null>(null);
  const [viewMode, setViewMode] = useState<DashboardView>('table');
  const [revealedFields, setRevealedFields] = useState<Record<string, boolean>>({});

  useEffect(() => {
    if (isAuthenticated) {
      setApps(storageService.getApplications());
    }
  }, [isAuthenticated]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (password === ADMIN_PASSWORD) {
      setIsAuthenticated(true);
    } else {
      alert("Invalid password");
    }
  };

  const toggleReveal = (appId: string) => {
    setRevealedFields(prev => ({
      ...prev,
      [appId]: !prev[appId]
    }));
  };

  const maskSSN = (ssn: string) => {
    if (!ssn) return 'N/A';
    const clean = ssn.replace(/\D/g, '');
    if (clean.length < 4) return ssn;
    return `***-**-${clean.slice(-4)}`;
  };

  const updateStatus = (id: string, status: LeadApplication['status']) => {
    storageService.updateApplicationStatus(id, status);
    const updatedApps = storageService.getApplications();
    setApps(updatedApps);
    if (selectedApp?.id === id) {
      setSelectedApp(updatedApps.find(a => a.id === id) || null);
    }
  };

  const deleteApp = (id: string) => {
    if (confirm("Are you sure you want to delete this application? This cannot be undone.")) {
      storageService.deleteApplication(id);
      setApps(storageService.getApplications());
      setSelectedApp(null);
      setViewMode('table');
    }
  };

  const downloadFile = (doc: { data: string, name: string }) => {
    const link = document.createElement('a');
    link.href = doc.data;
    link.download = doc.name;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handlePrint = () => {
    window.print();
  };

  const getScoreColor = (score: number) => {
    if (score >= 60) return 'text-green-600 bg-green-50';
    if (score >= 40) return 'text-amber-600 bg-amber-50';
    return 'text-red-600 bg-red-50';
  };

  if (!isAuthenticated) {
    return (
      <div className="relative max-w-md mx-auto mt-20 p-8 bg-white rounded-3xl shadow-xl border border-slate-200 text-center animate-fade-in">
        {/* Back to Site Button */}
        <button 
          onClick={onLogout}
          className="absolute top-4 left-4 flex items-center gap-2 text-slate-400 hover:text-blue-600 font-bold text-xs transition-colors"
        >
          <i className="fa-solid fa-arrow-left"></i>
          <span>BACK TO SITE</span>
        </button>

        <div className="bg-slate-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-6 mt-4">
          <i className="fa-solid fa-shield-halved text-slate-400 text-2xl"></i>
        </div>
        <h2 className="text-2xl font-bold text-slate-900 mb-2">Heritage Sales Portal</h2>
        <p className="text-slate-500 text-sm mb-8">Unauthorized access is monitored.</p>
        <form onSubmit={handleLogin} className="space-y-4">
          <input 
            type="password" 
            autoFocus 
            className="w-full px-4 py-3 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-center text-lg tracking-widest" 
            placeholder="••••••••" 
            value={password} 
            onChange={e => setPassword(e.target.value)} 
          />
          <button className="w-full bg-slate-900 hover:bg-black text-white font-bold py-3 rounded-xl transition-all">Secure Login</button>
        </form>
      </div>
    );
  }

  const filteredApps = apps.filter(a => 
    a.applicant.name.toLowerCase().includes(search.toLowerCase()) || 
    a.applicant.phone.includes(search)
  );

  return (
    <div className="space-y-6 animate-fade-in print:p-0">
      {/* Dashboard Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 print:hidden">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <h2 className="text-3xl font-black text-slate-900">Sales Dashboard</h2>
            <span className="bg-blue-100 text-blue-700 text-[10px] font-bold px-2 py-0.5 rounded-full uppercase tracking-tighter flex items-center gap-1">
              <i className="fa-solid fa-lock text-[8px]"></i> Encrypted
            </span>
          </div>
          <p className="text-slate-500">Managing {apps.length} active leads</p>
        </div>

        <div className="flex items-center gap-3 w-full md:w-auto">
          {/* View Toggle */}
          <div className="flex bg-white border border-slate-200 rounded-xl overflow-hidden p-1 shadow-sm">
            <button 
              onClick={() => setViewMode('table')}
              className={`px-4 py-1.5 rounded-lg text-sm font-bold flex items-center gap-2 transition-all ${viewMode === 'table' ? 'bg-slate-900 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              <i className="fa-solid fa-table-list"></i> Table
            </button>
            <button 
              onClick={() => { if(selectedApp) setViewMode('profile'); else alert('Select an application first'); }}
              className={`px-4 py-1.5 rounded-lg text-sm font-bold flex items-center gap-2 transition-all ${viewMode === 'profile' ? 'bg-slate-900 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              <i className="fa-solid fa-address-card"></i> Profile
            </button>
          </div>

          <div className="h-8 w-px bg-slate-200 mx-1 hidden md:block"></div>

          {/* Navigation/Logout Actions */}
          <div className="flex items-center gap-2">
            <button 
              onClick={onLogout}
              className="bg-white border border-slate-200 text-slate-600 px-4 py-2.5 rounded-xl font-bold text-sm hover:bg-slate-50 transition-all shadow-sm flex items-center gap-2"
            >
              <i className="fa-solid fa-house"></i>
              <span className="hidden sm:inline">Main Site</span>
            </button>
            <button 
              onClick={onLogout}
              className="bg-red-50 text-red-600 px-4 py-2.5 rounded-xl font-bold text-sm hover:bg-red-600 hover:text-white transition-all shadow-sm flex items-center gap-2 border border-red-100"
            >
              <i className="fa-solid fa-right-from-bracket"></i>
              <span className="hidden sm:inline">Log Out</span>
            </button>
          </div>
        </div>
      </div>

      <div className="print:hidden">
        {viewMode === 'table' ? (
