                  <div className="p-8 border-b border-slate-100 bg-slate-900 text-white flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                    <div className="flex items-center gap-6">
                      <div className={`w-20 h-20 rounded-3xl flex items-center justify-center text-3xl font-black text-white shrink-0 shadow-2xl ${selectedApp.applicant.internalScore >= 60 ? 'bg-green-500 shadow-green-500/30' : selectedApp.applicant.internalScore >= 40 ? 'bg-amber-500 shadow-amber-500/30' : 'bg-red-500 shadow-red-500/30'}`}>
