              <p className="text-[7px] text-slate-500 mt-8 italic leading-tight text-center">
                This document is for internal verification by Heritage Housing Sales Personnel only. Any unauthorized duplication or distribution is strictly prohibited. Final approval is subject to manual verification of all submitted bank statements and pay stubs.
              </p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const DataRow = ({ label, value, masked = false, colSpan = 1 }: { label: string, value: string, masked?: boolean, colSpan?: number }) => (
  <div className={`space-y-1 ${colSpan > 1 ? 'md:col-span-2' : ''}`}>
    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{label}</p>
    <p className={`text-sm font-bold text-slate-900 border-b border-slate-50 pb-1 ${masked ? 'blur-[4px] select-none opacity-50' : ''}`}>
      {value || 'Not Provided'}
    </p>
  </div>
);

const PrintField = ({ label, value, colSpan = 1 }: { label: string, value: string, colSpan?: number }) => (
  <div className={colSpan > 1 ? 'col-span-2' : ''}>
    <p className="text-[8px] font-bold text-slate-500 uppercase tracking-tighter leading-none mb-1">{label}</p>
    <p className="text-sm font-black text-black border-b border-slate-200 pb-1">{value || 'N/A'}</p>
  </div>
);

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { AppStep, ApplicationData, CoSignerData, DocumentFile, LeadApplication, Language } from './types';
import LandingPage from './components/LandingPage';
import UnifiedApplicationForm from './components/UnifiedApplicationForm';
import CoSignerForm from './components/CoSignerForm';
import DocumentUpload from './components/DocumentUpload';
import Dashboard from './components/Dashboard';
import SuccessScreen from './components/SuccessScreen';
import { storageService } from './services/storageService';
import { t } from './constants';

const App: React.FC = () => {
  const [currentStep, setCurrentStep] = useState<AppStep>('LANDING');
  const [language, setLanguage] = useState<Language>('English');
  const [applicantData, setApplicantData] = useState<ApplicationData | undefined>();
  const [cosignerData, setCosignerData] = useState<CoSignerData | undefined>();
  const [documents, setDocuments] = useState<DocumentFile[]>([]);

  const strings = t(language);

  useEffect(() => {
    if (window.location.hash === '#admin') {
      setCurrentStep('ADMIN_DASHBOARD');
    }
  }, []);

  const handleMainAppSubmit = (data: ApplicationData) => {
    setApplicantData(data);
    if (data.hasCoSigner) {
      setCurrentStep('CO_SIGNER');
    } else {
      setCurrentStep('DOCUMENTS');
    }
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleCoSignerSubmit = (data: CoSignerData) => {
    setCosignerData(data);
    setCurrentStep('DOCUMENTS');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDocumentSubmit = (docs: DocumentFile[]) => {
    if (!applicantData) return;

    const newApp: LeadApplication = {
      id: `APP-${Date.now()}`,
      status: 'Pending',
      applicant: applicantData,
      cosigner: cosignerData,
      documents: docs,
      submittedAt: new Date().toISOString()
    };

    storageService.saveApplication(newApp);
    setCurrentStep('SUCCESS');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const goToAdmin = () => {
    window.location.hash = 'admin';
    setCurrentStep('ADMIN_DASHBOARD');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const returnToPublic = () => {
    window.location.hash = '';
    window.location.reload();
  };

  const renderStep = () => {
    switch (currentStep) {
      case 'LANDING':
        return <LandingPage language={language} setLanguage={setLanguage} onStart={() => setCurrentStep('APPLICATION')} />;
      case 'APPLICATION':
        return (
          <UnifiedApplicationForm 
            language={language}
            onBack={() => setCurrentStep('LANDING')}
            onSubmit={handleMainAppSubmit} 
            initialData={applicantData} 
          />
        );
      case 'CO_SIGNER':
        return (
          <CoSignerForm 
            language={language}
            onBack={() => setCurrentStep('APPLICATION')} 
            onSubmit={handleCoSignerSubmit} 
            initialData={cosignerData}
          />
        );
      case 'DOCUMENTS':
        return (
          <DocumentUpload 
            language={language}
            onBack={() => applicantData?.hasCoSigner ? setCurrentStep('CO_SIGNER') : setCurrentStep('APPLICATION')} 
            onSubmit={handleDocumentSubmit}
            hasCosigner={!!applicantData?.hasCoSigner}
          />
        );
      case 'SUCCESS':
        return <SuccessScreen language={language} applicant={applicantData} onRestart={() => window.location.reload()} />;
      case 'ADMIN_DASHBOARD':
        return <Dashboard onLogout={returnToPublic} />;
      default:
        return <LandingPage language={language} setLanguage={setLanguage} onStart={() => setCurrentStep('APPLICATION')} />;
    }
  };

  return (
    <div className="min-h-screen pb-12">
      <header className="bg-slate-900 text-white shadow-lg sticky top-0 z-50">
        <div className="max-w-4xl mx-auto px-4 py-4 flex justify-between items-center">
          <div 
            className="flex items-center gap-3 cursor-pointer" 
            onClick={() => { if(currentStep !== 'ADMIN_DASHBOARD') window.location.reload(); }}
          >
            <div className="bg-white p-1.5 rounded-lg">
              <img src="https://cdn-icons-png.flaticon.com/512/25/25694.png" className="w-8 h-8" alt="Logo" />
            </div>
            <div>
              <h1 className="text-xl font-bold tracking-tight">Heritage Housing</h1>
              <p className="text-xs text-slate-400 font-medium uppercase tracking-widest">{strings.securePortal}</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
             {currentStep === 'ADMIN_DASHBOARD' ? (
                <button 
                  onClick={returnToPublic}
                  className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 px-4 py-2 rounded-xl text-xs font-black transition-all shadow-lg shadow-blue-900/20"
                >
                  <i className="fa-solid fa-house"></i>
                  <span>EXIT TO WEBSITE</span>
                </button>
             ) : (
                <button 
                  onClick={goToAdmin}
                  className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 border border-slate-700 px-3 py-2 rounded-xl text-xs font-black transition-all"
                >
                  <i className="fa-solid fa-lock text-blue-400"></i>
                  <span className="hidden sm:inline">{strings.salesPortal}</span>
                </button>
             )}
          </div>
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-4 pt-8">
        {renderStep()}
      </main>

      <footer className="mt-20 border-t border-slate-200 py-12 px-4 bg-white">
        <div className="max-w-4xl mx-auto">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
            <div>
              <h3 className="font-bold text-slate-900 mb-4 uppercase text-xs tracking-widest">Contact Sales</h3>
              <div className="space-y-4">
                <div className="flex items-center gap-3 text-slate-600">
                  <div className="w-8 h-8 bg-blue-50 rounded-full flex items-center justify-center text-blue-600">
                    <i className="fa-solid fa-phone text-sm"></i>
                  </div>
                  <div>
                    <p className="text-[10px] font-bold text-slate-400 uppercase">Miza</p>
                    <p className="font-bold text-sm">701-441-1388</p>
                  </div>
                </div>
                <div className="flex items-center gap-3 text-slate-600">
                  <div className="w-8 h-8 bg-blue-50 rounded-full flex items-center justify-center text-blue-600">
                    <i className="fa-solid fa-phone text-sm"></i>
                  </div>
                  <div>
                    <p className="text-[10px] font-bold text-slate-400 uppercase">Eva</p>
                    <p className="font-bold text-sm">405-268-2502</p>
                  </div>
                </div>
              </div>
            </div>

            <div className="bg-slate-50 p-6 rounded-2xl border border-slate-100">
              <h3 className="font-bold text-slate-900 mb-2 text-xs uppercase tracking-widest">Heritage Housing</h3>
              <p className="text-xs text-slate-500 leading-relaxed">
                Expert guidance for mobile home buyers. Secured with end-to-end encryption for your peace of mind.
              </p>
            </div>

            <div>
              <h3 className="font-bold text-slate-900 mb-4 uppercase text-xs tracking-widest">Staff Access</h3>
              <ul className="space-y-2">
                <li>
                  <button 
                    onClick={goToAdmin}
                    className="text-xs font-bold text-slate-400 hover:text-blue-600 transition-colors flex items-center gap-2"
                  >
                    <i className="fa-solid fa-shield-halved"></i> Employee Dashboard Login
                  </button>
                </li>
              </ul>
            </div>
          </div>

          <div className="mt-12 pt-8 border-t border-slate-100 text-center">
             <p className="text-[10px] font-bold text-slate-300 uppercase tracking-[0.3em]">
               © 2024 Heritage Housing Mobile Homes
             </p>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { LeadApplication } from '../types';
import { storageService } from '../services/storageService';
import { Icons, ADMIN_PASSWORD } from '../constants';

interface Props {
  onLogout: () => void;
}

type DashboardView = 'table' | 'profile';

const Dashboard: React.FC<Props> = ({ onLogout }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [password, setPassword] = useState('');
  const [apps, setApps] = useState<LeadApplication[]>([]);
  const [search, setSearch] = useState('');
  const [selectedApp, setSelectedApp] = useState<LeadApplication | null>(null);
  const [viewMode, setViewMode] = useState<DashboardView>('table');
  const [revealedFields, setRevealedFields] = useState<Record<string, boolean>>({});

  useEffect(() => {
    if (isAuthenticated) {
      setApps(storageService.getApplications());
    }
  }, [isAuthenticated]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (password === ADMIN_PASSWORD) {
      setIsAuthenticated(true);
    } else {
      alert("Invalid password");
    }
  };

  const toggleReveal = (appId: string) => {
    setRevealedFields(prev => ({
      ...prev,
      [appId]: !prev[appId]
    }));
  };

  const maskSSN = (ssn: string) => {
    if (!ssn) return 'N/A';
    const clean = ssn.replace(/\D/g, '');
    if (clean.length < 4) return ssn;
    return `***-**-${clean.slice(-4)}`;
  };

  const updateStatus = (id: string, status: LeadApplication['status']) => {
    storageService.updateApplicationStatus(id, status);
    const updatedApps = storageService.getApplications();
    setApps(updatedApps);
    if (selectedApp?.id === id) {
      setSelectedApp(updatedApps.find(a => a.id === id) || null);
    }
  };

  const deleteApp = (id: string) => {
    if (confirm("Are you sure you want to delete this application? This cannot be undone.")) {
      storageService.deleteApplication(id);
      setApps(storageService.getApplications());
      setSelectedApp(null);
      setViewMode('table');
    }
  };

  const downloadFile = (doc: { data: string, name: string }) => {
    const link = document.createElement('a');
    link.href = doc.data;
    link.download = doc.name;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handlePrint = () => {
    window.print();
  };

  const getScoreColor = (score: number) => {
    if (score >= 60) return 'text-green-600 bg-green-50';
    if (score >= 40) return 'text-amber-600 bg-amber-50';
    return 'text-red-600 bg-red-50';
  };

  if (!isAuthenticated) {
    return (
      <div className="relative max-w-md mx-auto mt-20 p-8 bg-white rounded-3xl shadow-xl border border-slate-200 text-center animate-fade-in">
        <button 
          onClick={onLogout}
          className="absolute top-4 left-4 flex items-center gap-2 text-blue-600 hover:text-blue-700 font-black text-xs transition-colors bg-blue-50 px-3 py-1.5 rounded-full"
        >
          <i className="fa-solid fa-house"></i>
          <span>BACK TO HOME</span>
        </button>

        <div className="bg-slate-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-6 mt-8">
          <i className="fa-solid fa-shield-halved text-slate-400 text-2xl"></i>
        </div>
        <h2 className="text-2xl font-bold text-slate-900 mb-2">Heritage Sales Portal</h2>
        <p className="text-slate-500 text-sm mb-8">Unauthorized access is monitored.</p>
        <form onSubmit={handleLogin} className="space-y-4">
          <input 
            type="password" 
            autoFocus 
            className="w-full px-4 py-3 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-center text-lg tracking-widest" 
            placeholder="••••••••" 
            value={password} 
            onChange={e => setPassword(e.target.value)} 
          />
          <button className="w-full bg-slate-900 hover:bg-black text-white font-bold py-3 rounded-xl transition-all">Secure Login</button>
        </form>
      </div>
    );
  }

  const filteredApps = apps.filter(a => 
    a.applicant.name.toLowerCase().includes(search.toLowerCase()) || 
    a.applicant.phone.includes(search)
  );

  return (
    <div className="space-y-6 animate-fade-in print:p-0">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 print:hidden">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <h2 className="text-3xl font-black text-slate-900">Sales Dashboard</h2>
            <span className="bg-blue-100 text-blue-700 text-[10px] font-bold px-2 py-0.5 rounded-full uppercase tracking-tighter flex items-center gap-1">
              <i className="fa-solid fa-lock text-[8px]"></i> Encrypted
            </span>
          </div>
          <p className="text-slate-500">Managing {apps.length} active leads</p>
        </div>

        <div className="flex items-center gap-3 w-full md:w-auto">
          <div className="flex bg-white border border-slate-200 rounded-xl overflow-hidden p-1 shadow-sm">
            <button 
              onClick={() => setViewMode('table')}
              className={`px-4 py-1.5 rounded-lg text-sm font-bold flex items-center gap-2 transition-all ${viewMode === 'table' ? 'bg-slate-900 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              <i className="fa-solid fa-table-list"></i> Table
            </button>
            <button 
              onClick={() => { if(selectedApp) setViewMode('profile'); else alert('Select an application first'); }}
              className={`px-4 py-1.5 rounded-lg text-sm font-bold flex items-center gap-2 transition-all ${viewMode === 'profile' ? 'bg-slate-900 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              <i className="fa-solid fa-address-card"></i> Profile
            </button>
          </div>

          <div className="h-8 w-px bg-slate-200 mx-1 hidden md:block"></div>

          <div className="flex items-center gap-2">
            <button 
              onClick={onLogout}
              className="bg-blue-600 text-white px-4 py-2.5 rounded-xl font-bold text-sm hover:bg-blue-700 transition-all shadow-md flex items-center gap-2"
            >
              <i className="fa-solid fa-house"></i>
              <span className="hidden sm:inline">Main Site</span>
            </button>
            <button 
              onClick={onLogout}
              className="bg-red-50 text-red-600 px-4 py-2.5 rounded-xl font-bold text-sm hover:bg-red-600 hover:text-white transition-all shadow-sm flex items-center gap-2 border border-red-100"
            >
              <i className="fa-solid fa-right-from-bracket"></i>
              <span className="hidden sm:inline">Log Out</span>
            </button>
          </div>
        </div>
      </div>

      <div className="print:hidden">
        {viewMode === 'table' ? (
          <div className="bg-white rounded-2xl border border-slate-200 shadow-xl overflow-hidden animate-fade-in">
            <div className="p-4 border-b border-slate-100 flex flex-col md:flex-row justify-between gap-4 bg-slate-50/50">
              <div className="relative flex-1">
                <i className="fa-solid fa-search absolute left-4 top-1/2 -translate-y-1/2 text-slate-400"></i>
                <input 
                  type="text" 
                  placeholder="Filter applications by name or phone..." 
                  className="w-full pl-10 pr-4 py-2.5 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none bg-white text-sm" 
                  value={search} 
                  onChange={e => setSearch(e.target.value)} 
                />
              </div>
              <button 
                onClick={() => setApps(storageService.getApplications())}
                className="bg-white border border-slate-200 px-4 py-2.5 rounded-xl text-sm font-bold hover:bg-slate-50 flex items-center justify-center gap-2 shadow-sm"
              >
                <i className="fa-solid fa-rotate"></i> Refresh
              </button>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm border-collapse">
                <thead>
                  <tr className="bg-slate-50 text-slate-500 border-b border-slate-100 font-bold">
                    <th className="px-6 py-4 whitespace-nowrap">ID / Date</th>
                    <th className="px-6 py-4">Applicant Name</th>
                    <th className="px-6 py-4">Status</th>
                    <th className="px-6 py-4 text-center">Score</th>
                    <th className="px-6 py-4">Income</th>
                    <th className="px-6 py-4">Rooms</th>
                    <th className="px-6 py-4">Documents</th>
                    <th className="px-6 py-4 text-right">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {filteredApps.length > 0 ? filteredApps.map(app => (
                    <tr 
                      key={app.id} 
                      className={`hover:bg-blue-50/30 transition-colors cursor-pointer group ${selectedApp?.id === app.id ? 'bg-blue-50/50' : ''}`}
                      onClick={() => { setSelectedApp(app); setViewMode('profile'); }}
                    >
                      <td className="px-6 py-4 whitespace-nowrap">
                        <p className="font-bold text-slate-900 text-xs">{app.id}</p>
                        <p className="text-[10px] text-slate-400 font-medium">{new Date(app.submittedAt).toLocaleDateString()}</p>
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-3">
                          <div className={`w-8 h-8 rounded-full flex items-center justify-center text-[10px] font-bold text-white shrink-0 ${app.applicant.internalScore >= 60 ? 'bg-green-500' : app.applicant.internalScore >= 40 ? 'bg-amber-500' : 'bg-red-500'}`}>
                            {app.applicant.name.charAt(0)}
                          </div>
                          <div>
                            <p className="font-black text-slate-900 leading-none">{app.applicant.name}</p>
                            <p className="text-[10px] text-slate-400 mt-1">{app.applicant.phone}</p>
                          </div>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <span className={`px-2 py-1 rounded-full text-[10px] font-black uppercase tracking-wider ${
                          app.status === 'Approved' ? 'bg-green-100 text-green-700' : 
                          app.status === 'Denied' ? 'bg-red-100 text-red-700' :
                          app.status === 'Reviewing' ? 'bg-amber-100 text-amber-700' :
                          'bg-slate-100 text-slate-600'
