                          {app.status}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-center">
                        <span className={`font-black text-sm ${getScoreColor(app.applicant.internalScore).split(' ')[0]}`}>
                          {app.applicant.internalScore}
