  const [currentStep, setCurrentStep] = useState<AppStep>('LANDING');
  const [language, setLanguage] = useState<Language>('English');
  const [applicantData, setApplicantData] = useState<ApplicationData | undefined>();
  const [cosignerData, setCosignerData] = useState<CoSignerData | undefined>();
  const [documents, setDocuments] = useState<DocumentFile[]>([]);

  const strings = t(language);

  // Listen for hash changes to allow deep linking and back-button support
  useEffect(() => {
    const handleHashChange = () => {
      if (window.location.hash === '#admin') {
        setCurrentStep('ADMIN_DASHBOARD');
      } else if (currentStep === 'ADMIN_DASHBOARD') {
        // If we were in admin and the hash is cleared, go home
        setCurrentStep('LANDING');
      }
    };

    // Initial check
    handleHashChange();

    window.addEventListener('hashchange', handleHashChange);
    return () => window.removeEventListener('hashchange', handleHashChange);
  }, [currentStep]);

  const handleMainAppSubmit = (data: ApplicationData) => {
    setApplicantData(data);
    if (data.hasCoSigner) {
      setCurrentStep('CO_SIGNER');
    } else {
      setCurrentStep('DOCUMENTS');
    }
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleCoSignerSubmit = (data: CoSignerData) => {
    setCosignerData(data);
    setCurrentStep('DOCUMENTS');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDocumentSubmit = (docs: DocumentFile[]) => {
    if (!applicantData) return;

    const newApp: LeadApplication = {
      id: `APP-${Date.now()}`,
      status: 'Pending',
      applicant: applicantData,
      cosigner: cosignerData,
      documents: docs,
      submittedAt: new Date().toISOString()
    };

    storageService.saveApplication(newApp);
    setCurrentStep('SUCCESS');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const goToAdmin = () => {
    window.location.hash = 'admin';
    setCurrentStep('ADMIN_DASHBOARD');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const returnToPublic = () => {
    // Fixed: Use location.hash instead of pushState to avoid SecurityError in sandboxed/blob environments
    window.location.hash = '';
    setCurrentStep('LANDING');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const renderStep = () => {
    switch (currentStep) {
      case 'LANDING':
        return <LandingPage language={language} setLanguage={setLanguage} onStart={() => setCurrentStep('APPLICATION')} />;
      case 'APPLICATION':
        return (
          <UnifiedApplicationForm 
            language={language}
            onBack={() => setCurrentStep('LANDING')}
            onSubmit={handleMainAppSubmit} 
            initialData={applicantData} 
          />
